-- CRM draft workflow and device sync. No financial/offline posting commands.
CREATE TABLE crm.mobile_heads(company_id uuid PRIMARY KEY REFERENCES core.companies(id),sequence bigint NOT NULL DEFAULT 0 CHECK(sequence>=0));
CREATE TABLE crm.mobile_devices(id uuid NOT NULL,company_id uuid NOT NULL REFERENCES core.companies(id),actor_id uuid NOT NULL REFERENCES identity.users(id),last_sequence bigint NOT NULL DEFAULT 0 CHECK(last_sequence>=0),sync_epoch uuid NOT NULL DEFAULT gen_random_uuid(),cursor_expires_at timestamptz NOT NULL DEFAULT(now()+interval '30 days'),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id));
CREATE TABLE crm.mobile_drafts(id uuid NOT NULL,company_id uuid NOT NULL REFERENCES core.companies(id),kind text NOT NULL CHECK(kind IN('CUSTOMER','BRANCH','CONTACT')),customer_id uuid,owner_id uuid NOT NULL REFERENCES identity.users(id),state text NOT NULL DEFAULT 'DRAFT'CHECK(state IN('DRAFT','SUBMITTED','APPROVED','REJECTED','DELETED')),data jsonb NOT NULL CHECK(jsonb_typeof(data)='object'),version bigint NOT NULL DEFAULT 1 CHECK(version>0),formal_id uuid,reviewer_id uuid REFERENCES identity.users(id),reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,customer_id)REFERENCES crm.customers(company_id,id),CHECK((kind='CUSTOMER')=(customer_id IS NULL)));
CREATE TABLE crm.mobile_changes(company_id uuid NOT NULL,sequence bigint NOT NULL,draft_id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES identity.users(id),customer_id uuid,version bigint NOT NULL,tombstone boolean NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,sequence),FOREIGN KEY(company_id,draft_id)REFERENCES crm.mobile_drafts(company_id,id));
CREATE TABLE crm.mobile_operations(company_id uuid NOT NULL,operation_id uuid NOT NULL,device_id uuid NOT NULL,device_sequence bigint NOT NULL CHECK(device_sequence>0),request jsonb NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,operation_id),UNIQUE(company_id,device_id,device_sequence),FOREIGN KEY(company_id,device_id)REFERENCES crm.mobile_devices(company_id,id));
CREATE TABLE crm.contact_imports(id uuid NOT NULL,company_id uuid NOT NULL REFERENCES core.companies(id),customer_id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES identity.users(id),consent_reference text NOT NULL CHECK(length(consent_reference)BETWEEN 1 AND 200),rows jsonb NOT NULL CHECK(jsonb_typeof(rows)='array'),confirmed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,customer_id)REFERENCES crm.customers(company_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['mobile_heads','mobile_devices','mobile_drafts','mobile_changes','mobile_operations','contact_imports']LOOP EXECUTE format('ALTER TABLE crm.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE crm.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON crm.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);IF t IN('mobile_changes','mobile_operations')THEN EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON crm.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;END LOOP;END$$;
CREATE TRIGGER mobile_draft_version BEFORE UPDATE ON crm.mobile_drafts FOR EACH ROW EXECUTE FUNCTION core.touch_version();
CREATE INDEX ON crm.mobile_drafts(company_id,owner_id,state,updated_at,id);
INSERT INTO identity.permissions(code,description)VALUES('crm.drafts.read','Read owned CRM drafts'),('crm.drafts.write','Capture and submit owned CRM drafts'),('crm.drafts.review','Office review of CRM drafts'),('crm.mobile.sync','Register owned devices and sync CRM draft operations'),('crm.contacts.import','Preview selected consented phone contacts into drafts');
CREATE FUNCTION identity.seed_crm_mobile_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND((r.code IN('ADMIN','OFFICE','SALES')AND p.code IN('crm.drafts.read','crm.drafts.write','crm.mobile.sync','crm.contacts.import'))OR(r.code IN('ADMIN','OFFICE')AND p.code='crm.drafts.review'))ON CONFLICT DO NOTHING$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_crm_mobile_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION crm.mobile_permission(p text)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT EXISTS(SELECT 1 FROM identity.memberships m JOIN identity.users u ON u.id=m.user_id AND u.active JOIN identity.membership_roles mr ON mr.company_id=m.company_id AND mr.membership_id=m.id JOIN identity.role_permissions rp ON rp.company_id=mr.company_id AND rp.role_id=mr.role_id WHERE m.company_id=core.current_company()AND m.user_id=core.current_actor()AND m.active AND rp.permission_code=p)$$;
CREATE FUNCTION crm.require_mobile(p text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF NOT crm.mobile_permission(p)THEN RAISE EXCEPTION 'CRM permission denied' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION crm.mobile_reviewer()RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT crm.mobile_permission('crm.drafts.review')AND crm.mobile_permission('customers.write')AND crm.mobile_permission('customers.all')$$;
CREATE FUNCTION crm.mobile_customer_visible(p uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT p IS NULL OR(crm.mobile_permission('customers.read')AND EXISTS(SELECT 1 FROM crm.customers WHERE company_id=core.current_company()AND id=p)AND(crm.mobile_permission('customers.all')OR EXISTS(SELECT 1 FROM identity.customer_assignments a JOIN identity.memberships m ON m.company_id=a.company_id AND m.id=a.membership_id WHERE a.company_id=core.current_company()AND a.customer_id=p AND m.user_id=core.current_actor()AND m.active)))$$;
CREATE FUNCTION crm.lock_mobile_head()RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN INSERT INTO crm.mobile_heads(company_id)VALUES(core.current_company())ON CONFLICT DO NOTHING;PERFORM 1 FROM crm.mobile_heads WHERE company_id=core.current_company()FOR UPDATE;END$$;
CREATE FUNCTION crm.require_mobile_draft(p_id uuid,p_action text DEFAULT 'READ')RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d crm.mobile_drafts;BEGIN PERFORM crm.require_mobile('crm.drafts.read');SELECT*INTO d FROM crm.mobile_drafts WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'CRM draft unavailable' USING ERRCODE='HT404';END IF;IF NOT crm.mobile_customer_visible(d.customer_id)OR(d.owner_id<>core.current_actor()AND NOT crm.mobile_reviewer())THEN RAISE EXCEPTION 'CRM draft access denied' USING ERRCODE='42501';END IF;IF p_action='REVIEW'AND(NOT crm.mobile_reviewer()OR d.owner_id=core.current_actor())THEN RAISE EXCEPTION 'Independent office review required' USING ERRCODE='42501';END IF;IF p_action='WRITE'THEN PERFORM crm.require_mobile('crm.drafts.write');IF d.owner_id<>core.current_actor()THEN RAISE EXCEPTION 'Only draft owner may edit' USING ERRCODE='42501';END IF;END IF;END$$;
CREATE FUNCTION crm.draft_json(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile_draft(p_id,'READ');RETURN(SELECT jsonb_build_object('id',id,'kind',kind,'customerId',customer_id,'ownerId',owner_id,'state',state,'version',version,'data',CASE WHEN state='DELETED'THEN NULL ELSE data END,'formalId',formal_id,'reviewerId',reviewer_id,'reason',reason,'updatedAt',updated_at)FROM crm.mobile_drafts WHERE company_id=core.current_company()AND id=p_id);END$$;
CREATE FUNCTION crm.emit_draft(p_id uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE seq bigint;BEGIN UPDATE crm.mobile_heads SET sequence=sequence+1 WHERE company_id=core.current_company()RETURNING sequence INTO seq;INSERT INTO crm.mobile_changes(company_id,sequence,draft_id,owner_id,customer_id,version,tombstone,snapshot)SELECT company_id,seq,id,owner_id,customer_id,version,state='DELETED',crm.draft_json(id)FROM crm.mobile_drafts WHERE company_id=core.current_company()AND id=p_id;END$$;
CREATE FUNCTION crm.validate_draft(p_kind text,p_customer uuid,p_data jsonb)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE b uuid;BEGIN
 IF p_kind NOT IN('CUSTOMER','BRANCH','CONTACT')OR(p_kind='CUSTOMER')IS DISTINCT FROM(p_customer IS NULL)OR jsonb_typeof(p_data)IS DISTINCT FROM'object'OR coalesce(length(btrim(p_data->>'name')),0)NOT BETWEEN 1 AND 200 OR pg_column_size(p_data)>16000 THEN RAISE EXCEPTION 'Invalid CRM draft' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data)k WHERE k NOT IN('name','code','abn','email','phone','mobile','jobTitle','addressLine1','suburb','state','postcode','branchIds'))THEN RAISE EXCEPTION 'Unexpected draft property' USING ERRCODE='HR422';END IF;
 IF p_kind IN('CUSTOMER','BRANCH')AND coalesce(p_data->>'code','')!~'^[A-Z0-9][A-Z0-9_-]{0,39}$'OR p_kind='CUSTOMER'AND NOT core.valid_abn(p_data->>'abn')THEN RAISE EXCEPTION 'Invalid code or Australian ABN' USING ERRCODE='HR422';END IF;
 IF p_kind='BRANCH'AND(coalesce(length(btrim(p_data->>'addressLine1')),0)NOT BETWEEN 1 AND 300 OR coalesce(p_data->>'state','')NOT IN('ACT','NSW','NT','QLD','SA','TAS','VIC','WA')OR coalesce(p_data->>'postcode','')!~'^[0-9]{4}$')THEN RAISE EXCEPTION 'Australian address required' USING ERRCODE='HR422';END IF;
 IF p_kind='CONTACT'THEN IF coalesce(length(p_data->>'email'),0)>254 OR(p_data->>'email')IS NOT NULL AND(p_data->>'email')!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'OR coalesce(length(p_data->>'phone'),0)>40 OR coalesce(length(p_data->>'mobile'),0)>40 OR coalesce(length(p_data->>'jobTitle'),0)>100 OR jsonb_typeof(p_data->'branchIds')IS DISTINCT FROM'array'OR jsonb_array_length(p_data->'branchIds')>50 THEN RAISE EXCEPTION 'Invalid contact details' USING ERRCODE='HR422';END IF;FOR b IN SELECT value::uuid FROM jsonb_array_elements_text(p_data->'branchIds')LOOP IF NOT EXISTS(SELECT 1 FROM crm.customer_branches WHERE company_id=core.current_company()AND customer_id=p_customer AND id=b AND active)THEN RAISE EXCEPTION 'Branch outside target customer' USING ERRCODE='HR422';END IF;END LOOP;END IF;
END$$;
CREATE FUNCTION crm.create_mobile_draft(p_id uuid,p_kind text,p_customer uuid,p_data jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.drafts.write');PERFORM crm.require_mobile('crm.drafts.read');IF NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Target customer access denied' USING ERRCODE='42501';END IF;PERFORM crm.validate_draft(p_kind,p_customer,p_data);IF p_id IS NULL OR p_id='00000000-0000-0000-0000-000000000000'THEN RAISE EXCEPTION 'Draft ID required' USING ERRCODE='HR422';END IF;PERFORM crm.lock_mobile_head();PERFORM crm.require_mobile('crm.drafts.write');IF NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Customer access changed' USING ERRCODE='42501';END IF;IF EXISTS(SELECT 1 FROM crm.mobile_drafts WHERE company_id=core.current_company()AND id=p_id)THEN RAISE EXCEPTION 'Draft ID already exists' USING ERRCODE='HR409';END IF;INSERT INTO crm.mobile_drafts(id,company_id,kind,customer_id,owner_id,data)VALUES(p_id,core.current_company(),p_kind,p_customer,core.current_actor(),p_data);PERFORM crm.emit_draft(p_id);RETURN crm.draft_json(p_id);END$$;
CREATE FUNCTION crm.change_mobile_draft(p_id uuid,p_version bigint,p_action text,p_data jsonb DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d crm.mobile_drafts;BEGIN PERFORM crm.require_mobile_draft(p_id,'WRITE');PERFORM crm.lock_mobile_head();PERFORM crm.require_mobile_draft(p_id,CASE WHEN p_action IS NOT NULL THEN'WRITE'ELSE'READ'END);SELECT*INTO d FROM crm.mobile_drafts WHERE company_id=core.current_company()AND id=p_id FOR UPDATE;IF d.version IS DISTINCT FROM p_version OR d.state<>'DRAFT'THEN RAISE EXCEPTION 'Draft version or state conflict' USING ERRCODE='HR409';END IF;IF p_action='UPDATE'THEN PERFORM crm.validate_draft(d.kind,d.customer_id,p_data);UPDATE crm.mobile_drafts SET data=p_data WHERE company_id=d.company_id AND id=d.id;ELSIF p_action IN('SUBMIT','DELETE')THEN UPDATE crm.mobile_drafts SET state=CASE WHEN p_action='SUBMIT'THEN'SUBMITTED'ELSE'DELETED'END,data=CASE WHEN p_action='DELETE'THEN'{}'::jsonb ELSE data END WHERE company_id=d.company_id AND id=d.id;ELSE RAISE EXCEPTION 'Unsupported draft operation' USING ERRCODE='HR422';END IF;PERFORM crm.emit_draft(p_id);RETURN crm.draft_json(p_id);END$$;
CREATE FUNCTION crm.mobile_phone_key(p text)RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT CASE WHEN x~'^0[0-9]{9}$'THEN'+61'||substr(x,2)ELSE x END FROM(SELECT regexp_replace(p,'[(). -]','','g')AS x)s$$;
REVOKE ALL ON FUNCTION crm.mobile_phone_key(text)FROM PUBLIC;
-- Duplicates are suggestions, never an automatic merge of customer identities.
CREATE FUNCTION crm.mobile_duplicates(p_kind text,p_customer uuid,p_data jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.drafts.read');IF NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Target customer denied' USING ERRCODE='42501';END IF;RETURN(SELECT coalesce(jsonb_agg(x),'[]')FROM(
 SELECT cu.id,'CUSTOMER'::text AS kind FROM crm.customers cu JOIN crm.parties pa ON pa.company_id=cu.company_id AND pa.id=cu.party_id WHERE cu.company_id=core.current_company()AND crm.mobile_customer_visible(cu.id)AND p_kind='CUSTOMER'AND(lower(pa.legal_name)=lower(p_data->>'name')OR pa.abn=p_data->>'abn'OR cu.code=p_data->>'code')
 UNION ALL SELECT id,'BRANCH' FROM crm.customer_branches WHERE company_id=core.current_company()AND customer_id=p_customer AND p_kind='BRANCH'AND(code=p_data->>'code'OR lower(name)=lower(p_data->>'name'))
 UNION ALL SELECT co.id,'CONTACT'FROM crm.contacts co JOIN crm.customers cu ON cu.company_id=co.company_id AND cu.party_id=co.party_id WHERE co.company_id=core.current_company()AND cu.id=p_customer AND p_kind='CONTACT'AND(lower(co.name)=lower(p_data->>'name')OR lower(co.email)=lower(p_data->>'email')OR crm.mobile_phone_key(co.mobile)IN(crm.mobile_phone_key(p_data->>'mobile'),crm.mobile_phone_key(p_data->>'phone'))OR crm.mobile_phone_key(co.phone)IN(crm.mobile_phone_key(p_data->>'mobile'),crm.mobile_phone_key(p_data->>'phone'))) LIMIT 20)x);END$$;
CREATE FUNCTION crm.review_mobile_draft(p_id uuid,p_version bigint,p_approve boolean,p_reason text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();d crm.mobile_drafts;fid uuid:=gen_random_uuid();party uuid;b uuid;terms int;BEGIN
 PERFORM crm.require_mobile_draft(p_id,'REVIEW');IF coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Review reason required' USING ERRCODE='HR422';END IF;PERFORM crm.lock_mobile_head();PERFORM crm.require_mobile_draft(p_id,'REVIEW');SELECT*INTO d FROM crm.mobile_drafts WHERE company_id=c AND id=p_id FOR UPDATE;IF d.version IS DISTINCT FROM p_version OR d.state<>'SUBMITTED'THEN RAISE EXCEPTION 'Draft is not reviewable at supplied version' USING ERRCODE='HR409';END IF;
 IF p_approve THEN PERFORM crm.validate_draft(d.kind,d.customer_id,d.data);IF crm.mobile_duplicates(d.kind,d.customer_id,d.data)<>'[]'::jsonb THEN RAISE EXCEPTION 'Potential duplicate; review existing master data and reject this draft if already present' USING ERRCODE='HR409';END IF;
 IF d.kind='CUSTOMER'THEN SELECT sales_terms_days INTO terms FROM core.business_preferences WHERE company_id=c FOR SHARE;IF terms IS NULL THEN RAISE EXCEPTION 'Company default sales terms missing' USING ERRCODE='HR422';END IF;INSERT INTO crm.parties(company_id,legal_name,abn,created_by)VALUES(c,d.data->>'name',d.data->>'abn',core.current_actor())RETURNING id INTO party;INSERT INTO crm.customers(id,company_id,party_id,code,credit_limit,payment_terms_days,created_by)VALUES(fid,c,party,d.data->>'code',0,terms,core.current_actor());INSERT INTO crm.customer_credit_exposures(company_id,customer_id,created_by)VALUES(c,fid,core.current_actor());INSERT INTO identity.customer_assignments(company_id,membership_id,customer_id,created_by)SELECT c,id,fid,core.current_actor()FROM identity.memberships WHERE company_id=c AND user_id=d.owner_id AND active ON CONFLICT DO NOTHING;
 ELSIF d.kind='BRANCH'THEN INSERT INTO crm.customer_branches(id,company_id,customer_id,code,name,address_line1,suburb,state,postcode,country,created_by)VALUES(fid,c,d.customer_id,d.data->>'code',d.data->>'name',d.data->>'addressLine1',d.data->>'suburb',d.data->>'state',d.data->>'postcode','AU',core.current_actor());
 ELSE SELECT party_id INTO party FROM crm.customers WHERE company_id=c AND id=d.customer_id;IF EXISTS(SELECT 1 FROM crm.suppliers WHERE company_id=c AND party_id=party)AND NOT crm.mobile_permission('suppliers.write')THEN RAISE EXCEPTION 'Shared supplier party requires supplier permission' USING ERRCODE='42501';END IF;INSERT INTO crm.contacts(id,company_id,party_id,name,email,phone,mobile,job_title,created_by)VALUES(fid,c,party,d.data->>'name',d.data->>'email',d.data->>'phone',d.data->>'mobile',d.data->>'jobTitle',core.current_actor());FOR b IN SELECT DISTINCT value::uuid FROM jsonb_array_elements_text(d.data->'branchIds')LOOP INSERT INTO crm.contact_branch_links(company_id,contact_id,customer_branch_id,created_by)VALUES(c,fid,b,core.current_actor());END LOOP;END IF;END IF;
 UPDATE crm.mobile_drafts SET state=CASE WHEN p_approve THEN'APPROVED'ELSE'REJECTED'END,formal_id=CASE WHEN p_approve THEN fid ELSE NULL END,reviewer_id=core.current_actor(),reason=btrim(p_reason)WHERE company_id=c AND id=p_id;PERFORM crm.emit_draft(p_id);RETURN crm.draft_json(p_id);
END$$;
CREATE FUNCTION crm.mobile_auth_hash()RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT md5(coalesce((SELECT string_agg(x,'|'ORDER BY x)FROM(SELECT rp.permission_code AS x FROM identity.memberships m JOIN identity.membership_roles mr ON mr.company_id=m.company_id AND mr.membership_id=m.id JOIN identity.role_permissions rp ON rp.company_id=mr.company_id AND rp.role_id=mr.role_id WHERE m.company_id=core.current_company()AND m.user_id=core.current_actor()AND m.active UNION SELECT a.id::text||':'||a.version::text FROM identity.customer_assignments a JOIN identity.memberships m ON m.company_id=a.company_id AND m.id=a.membership_id WHERE a.company_id=core.current_company()AND m.user_id=core.current_actor()AND m.active)s),''))$$;
CREATE FUNCTION crm.require_mobile_device(p uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.mobile.sync');PERFORM crm.require_mobile('crm.drafts.read');IF NOT EXISTS(SELECT 1 FROM crm.mobile_devices WHERE company_id=core.current_company()AND id=p AND actor_id=core.current_actor()AND active)THEN RAISE EXCEPTION 'Device access denied' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION crm.register_mobile_device(p uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.mobile.sync');IF p IS NULL OR p='00000000-0000-0000-0000-000000000000'THEN RAISE EXCEPTION 'Device ID required' USING ERRCODE='HR422';END IF;INSERT INTO crm.mobile_devices(id,company_id,actor_id)VALUES(p,core.current_company(),core.current_actor())ON CONFLICT DO NOTHING;PERFORM crm.require_mobile_device(p);RETURN jsonb_build_object('deviceId',p,'lastSequence',(SELECT last_sequence FROM crm.mobile_devices WHERE company_id=core.current_company()AND id=p),'auth',crm.mobile_auth_hash());END$$;
CREATE FUNCTION crm.mobile_push(p_device uuid,p_operation uuid,p_sequence bigint,p_request jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$#variable_conflict use_variable
DECLARE c uuid:=core.current_company();dev crm.mobile_devices;old crm.mobile_operations;res jsonb;d crm.mobile_drafts;id uuid:=(p_request->>'id')::uuid;action text:=p_request->>'action';BEGIN
 PERFORM crm.require_mobile_device(p_device);PERFORM crm.require_mobile('crm.drafts.write');IF p_operation IS NULL OR p_sequence<=0 THEN RAISE EXCEPTION 'Operation identity required' USING ERRCODE='HR422';END IF;
 -- Authorize the target before replay, including operations cached before a scope revocation.
 IF action='CREATE'THEN IF NOT crm.mobile_customer_visible((p_request->>'customerId')::uuid)THEN RAISE EXCEPTION 'Target customer access denied' USING ERRCODE='42501';END IF;ELSE PERFORM crm.require_mobile_draft(id,'WRITE');END IF;
 PERFORM crm.lock_mobile_head();SELECT*INTO dev FROM crm.mobile_devices md WHERE md.company_id=c AND md.id=p_device FOR UPDATE;PERFORM crm.require_mobile_device(p_device);IF action='CREATE'THEN IF NOT crm.mobile_customer_visible((p_request->>'customerId')::uuid)THEN RAISE EXCEPTION 'Customer scope changed' USING ERRCODE='42501';END IF;ELSE PERFORM crm.require_mobile_draft(id,'WRITE');END IF;SELECT*INTO old FROM crm.mobile_operations WHERE company_id=c AND operation_id=p_operation;
 IF FOUND THEN IF old.device_id<>p_device OR old.device_sequence<>p_sequence OR old.request<>p_request THEN RAISE EXCEPTION 'Operation ID reused with different request' USING ERRCODE='HR409';END IF;RETURN old.response;END IF;
 IF dev.last_sequence+1<>p_sequence THEN RAISE EXCEPTION 'Device sequence gap or conflicting replay' USING ERRCODE='HR409';END IF;
 BEGIN IF action='CREATE'THEN res:=crm.create_mobile_draft(id,p_request->>'kind',(p_request->>'customerId')::uuid,p_request->'data');ELSE res:=crm.change_mobile_draft(id,(p_request->>'version')::bigint,action,p_request->'data');END IF;res:=jsonb_build_object('status','APPLIED','draft',res);
 EXCEPTION WHEN SQLSTATE'HR409'THEN res:=jsonb_build_object('status','CONFLICT','id',id,'serverVersion',(SELECT version FROM crm.mobile_drafts WHERE company_id=c AND mobile_drafts.id=id AND(owner_id=core.current_actor()OR crm.mobile_reviewer())AND crm.mobile_customer_visible(customer_id)));END;
 UPDATE crm.mobile_devices SET last_sequence=p_sequence WHERE company_id=c AND mobile_devices.id=p_device;INSERT INTO crm.mobile_operations(company_id,operation_id,device_id,device_sequence,request,response)VALUES(c,p_operation,p_device,p_sequence,p_request,res);RETURN res;
END$$;
CREATE FUNCTION crm.mobile_pull(p_device uuid,p_after bigint,p_auth text,p_limit int DEFAULT 100)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE high bigint;next_seq bigint;items jsonb;auth text;dev crm.mobile_devices;BEGIN
 PERFORM crm.require_mobile_device(p_device);IF p_after<0 OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid sync page' USING ERRCODE='HR422';END IF;
 -- Commit-ordered head plus device epoch: scope changes, expiry and reset invalidate old cursors.
 PERFORM crm.lock_mobile_head();SELECT*INTO dev FROM crm.mobile_devices WHERE company_id=core.current_company()AND id=p_device FOR UPDATE;PERFORM crm.require_mobile_device(p_device);
 IF p_after=0 THEN UPDATE crm.mobile_devices SET sync_epoch=gen_random_uuid(),cursor_expires_at=now()+interval '30 days'WHERE company_id=core.current_company()AND id=p_device RETURNING*INTO dev;END IF;auth:=md5(crm.mobile_auth_hash()||dev.sync_epoch::text);
 IF p_after>0 AND(p_auth IS DISTINCT FROM auth OR dev.cursor_expires_at<=now())THEN RAISE EXCEPTION 'Cursor expired or authorization changed; discard cached CRM objects and restart at zero' USING ERRCODE='HR409';END IF;
 SELECT sequence INTO high FROM crm.mobile_heads WHERE company_id=core.current_company();IF p_after>high THEN RAISE EXCEPTION 'Cursor ahead of server; reset required' USING ERRCODE='HR409';END IF;
 SELECT coalesce(max(sequence),p_after),coalesce(jsonb_agg(jsonb_build_object('sequence',sequence,'tombstone',tombstone,'draft',snapshot)ORDER BY sequence)FILTER(WHERE(owner_id=core.current_actor()OR crm.mobile_reviewer())AND crm.mobile_customer_visible(customer_id)),'[]')INTO next_seq,items FROM(SELECT*FROM crm.mobile_changes WHERE company_id=core.current_company()AND sequence>p_after ORDER BY sequence LIMIT p_limit)s;RETURN jsonb_build_object('items',items,'nextSequence',next_seq,'auth',auth,'hasMore',next_seq<high,'resetRequired',false,'cursorExpiresAt',dev.cursor_expires_at);
END$$;
CREATE FUNCTION crm.preview_contact_import(p_id uuid,p_customer uuid,p_consent text,p_rows jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE x jsonb;built jsonb:='[]';seen jsonb:='[]';key text;keys jsonb;duplicate boolean;BEGIN PERFORM crm.require_mobile('crm.contacts.import');PERFORM crm.require_mobile('crm.drafts.write');PERFORM crm.require_mobile('crm.drafts.read');IF NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Customer access denied' USING ERRCODE='42501';END IF;IF coalesce(length(btrim(p_consent)),0)NOT BETWEEN 1 AND 200 OR jsonb_typeof(p_rows)IS DISTINCT FROM'array'OR jsonb_array_length(p_rows)NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Selected contacts and consent reference required' USING ERRCODE='HR422';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p_rows)LOOP PERFORM crm.validate_draft('CONTACT',p_customer,x);keys:=jsonb_build_array(lower(x->>'name'));IF x->>'email'IS NOT NULL THEN keys:=keys||to_jsonb('email:'||(x->>'email'));END IF;IF x->>'mobile'IS NOT NULL THEN keys:=keys||to_jsonb('phone:'||(x->>'mobile'));END IF;IF x->>'phone'IS NOT NULL THEN keys:=keys||to_jsonb('phone:'||(x->>'phone'));END IF;SELECT EXISTS(SELECT 1 FROM jsonb_array_elements_text(keys)k WHERE seen?k)INTO duplicate;built:=built||jsonb_build_array(jsonb_build_object('row',jsonb_array_length(built),'data',x,'withinBatchDuplicate',duplicate,'duplicates',crm.mobile_duplicates('CONTACT',p_customer,x)));seen:=seen||keys;END LOOP;
 INSERT INTO crm.contact_imports(id,company_id,customer_id,owner_id,consent_reference,rows)VALUES(p_id,core.current_company(),p_customer,core.current_actor(),btrim(p_consent),built);RETURN jsonb_build_object('id',p_id,'rows',built);
END$$;
CREATE FUNCTION crm.require_contact_import(p_id uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE x crm.contact_imports;BEGIN PERFORM crm.require_mobile('crm.contacts.import');PERFORM crm.require_mobile('crm.drafts.write');PERFORM crm.require_mobile('crm.drafts.read');SELECT*INTO x FROM crm.contact_imports WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Import unavailable' USING ERRCODE='HT404';END IF;IF x.owner_id<>core.current_actor()OR NOT crm.mobile_customer_visible(x.customer_id)THEN RAISE EXCEPTION 'Import access denied' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION crm.confirm_contact_import(p_id uuid,p_rows int[])RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE x crm.contact_imports;r int;e jsonb;fid uuid;ids jsonb:='[]';BEGIN PERFORM crm.require_contact_import(p_id);PERFORM crm.lock_mobile_head();PERFORM crm.require_contact_import(p_id);SELECT*INTO x FROM crm.contact_imports WHERE company_id=core.current_company()AND id=p_id FOR UPDATE;IF x.confirmed THEN RAISE EXCEPTION 'Import already confirmed' USING ERRCODE='HR409';END IF;IF cardinality(p_rows)NOT BETWEEN 1 AND 100 OR cardinality(p_rows)<>(SELECT count(DISTINCT v)FROM unnest(p_rows)v)THEN RAISE EXCEPTION 'Select distinct preview rows' USING ERRCODE='HR422';END IF;
 FOREACH r IN ARRAY p_rows LOOP e:=x.rows->r;IF r<0 OR e IS NULL OR(e->>'withinBatchDuplicate')::boolean OR crm.mobile_duplicates('CONTACT',x.customer_id,e->'data')<>'[]'::jsonb THEN RAISE EXCEPTION 'Duplicate or invalid preview selection' USING ERRCODE='HR409';END IF;fid:=gen_random_uuid();PERFORM crm.create_mobile_draft(fid,'CONTACT',x.customer_id,e->'data');ids:=ids||to_jsonb(fid);END LOOP;UPDATE crm.contact_imports SET confirmed=true WHERE company_id=x.company_id AND id=x.id;RETURN jsonb_build_object('id',p_id,'draftIds',ids);
END$$;
-- Private helpers are not callable as the app. Public operations recheck permissions in SQL.
DO $$DECLARE p record;BEGIN FOR p IN SELECT oid::regprocedure AS fn FROM pg_proc WHERE pronamespace='crm'::regnamespace AND(proname LIKE '%mobile%'OR proname IN('draft_json','emit_draft','validate_draft','mobile_duplicates','preview_contact_import','require_contact_import','confirm_contact_import'))LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p.fn);END LOOP;END$$;
REVOKE ALL ON FUNCTION identity.seed_crm_mobile_roles(uuid)FROM PUBLIC;
GRANT SELECT ON crm.mobile_heads,crm.mobile_devices,crm.mobile_drafts,crm.mobile_changes,crm.mobile_operations,crm.contact_imports TO htt_app;
GRANT EXECUTE ON FUNCTION crm.require_mobile(text),crm.mobile_reviewer(),crm.mobile_customer_visible(uuid),crm.require_mobile_draft(uuid,text),crm.draft_json(uuid),crm.mobile_duplicates(text,uuid,jsonb),crm.create_mobile_draft(uuid,text,uuid,jsonb),crm.change_mobile_draft(uuid,bigint,text,jsonb),crm.review_mobile_draft(uuid,bigint,boolean,text),crm.require_mobile_device(uuid),crm.register_mobile_device(uuid),crm.mobile_push(uuid,uuid,bigint,jsonb),crm.mobile_pull(uuid,bigint,text,int),crm.preview_contact_import(uuid,uuid,text,jsonb),crm.require_contact_import(uuid),crm.confirm_contact_import(uuid,int[])TO htt_app;
-- Private selected-card images: scanned before OCR, suggestions require human confirmation.
CREATE TABLE crm.card_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),customer_id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES identity.users(id),content bytea NOT NULL CHECK(octet_length(content)BETWEEN 1 AND 10485760),content_type text NOT NULL CHECK(content_type IN('image/png','image/jpeg')),state text NOT NULL DEFAULT 'PENDING'CHECK(state IN('PENDING','PROCESSING','RETRY','FAILED','REJECTED','SUCCEEDED')),attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),lease_token uuid,lease_until timestamptz,available_at timestamptz NOT NULL DEFAULT now(),suggestion jsonb,last_error text,draft_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,customer_id)REFERENCES crm.customers(company_id,id),FOREIGN KEY(company_id,draft_id)REFERENCES crm.mobile_drafts(company_id,id));
ALTER TABLE crm.card_jobs ENABLE ROW LEVEL SECURITY;ALTER TABLE crm.card_jobs FORCE ROW LEVEL SECURITY;CREATE POLICY company_scope ON crm.card_jobs USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company());CREATE INDEX ON crm.card_jobs(available_at,created_at)WHERE state IN('PENDING','RETRY','PROCESSING');
CREATE FUNCTION crm.require_card(p_id uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.card_jobs;BEGIN PERFORM crm.require_mobile('crm.contacts.import');PERFORM crm.require_mobile('crm.drafts.read');PERFORM crm.require_mobile('crm.drafts.write');SELECT*INTO j FROM crm.card_jobs WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Card job unavailable' USING ERRCODE='HT404';END IF;IF j.owner_id<>core.current_actor()OR NOT crm.mobile_customer_visible(j.customer_id)THEN RAISE EXCEPTION 'Card job access denied' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION crm.card_view(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.card_jobs;BEGIN PERFORM crm.require_card(p_id);SELECT*INTO j FROM crm.card_jobs WHERE company_id=core.current_company()AND id=p_id;RETURN jsonb_build_object('id',j.id,'customerId',j.customer_id,'state',j.state,'attempts',j.attempts,'suggestion',j.suggestion,'lastError',j.last_error,'draftId',j.draft_id,'createdAt',j.created_at);END$$;
CREATE FUNCTION crm.queue_card(p_customer uuid,p_type text,p_bytes bytea)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE id uuid;BEGIN PERFORM crm.require_mobile('crm.contacts.import');PERFORM crm.require_mobile('crm.drafts.write');PERFORM crm.require_mobile('crm.drafts.read');IF NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Customer access denied' USING ERRCODE='42501';END IF;IF octet_length(p_bytes)NOT BETWEEN 1 AND 10485760 OR p_type NOT IN('image/png','image/jpeg')THEN RAISE EXCEPTION 'Selected card image required' USING ERRCODE='HR422';END IF;INSERT INTO crm.card_jobs(company_id,customer_id,owner_id,content,content_type)VALUES(core.current_company(),p_customer,core.current_actor(),p_bytes,p_type)RETURNING card_jobs.id INTO id;RETURN id;END$$;
CREATE FUNCTION crm.retry_card(p_id uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_card(p_id);UPDATE crm.card_jobs SET state='PENDING',attempts=0,last_error=NULL,available_at=now(),lease_token=NULL,lease_until=NULL WHERE company_id=core.current_company()AND id=p_id AND state='FAILED';IF NOT FOUND THEN RAISE EXCEPTION 'Only failed jobs may be manually retried' USING ERRCODE='HR409';END IF;END$$;
CREATE FUNCTION crm.claim_card()RETURNS TABLE(job_id uuid,lease uuid)LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.card_jobs;tok uuid;BEGIN
 -- Recover expired work with bounded attempts. OCR is read-only and safe to repeat.
 UPDATE crm.card_jobs SET state='FAILED',last_error='attempts_exhausted',lease_token=NULL,lease_until=NULL WHERE state='PROCESSING'AND lease_until<now()AND attempts>=5;
 SELECT*INTO j FROM crm.card_jobs WHERE(state IN('PENDING','RETRY')AND available_at<=now()OR state='PROCESSING'AND lease_until<now())AND attempts<5 ORDER BY available_at,created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;IF NOT FOUND THEN RETURN;END IF;tok:=gen_random_uuid();UPDATE crm.card_jobs SET state='PROCESSING',attempts=attempts+1,lease_token=tok,lease_until=now()+interval '2 minutes'WHERE id=j.id;RETURN QUERY SELECT j.id,tok;
END$$;
CREATE FUNCTION crm.load_card(p_id uuid,p_lease uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.card_jobs;BEGIN SELECT*INTO j FROM crm.card_jobs WHERE id=p_id AND state='PROCESSING'AND lease_token=p_lease AND lease_until>now();IF NOT FOUND THEN RAISE EXCEPTION 'Card lease unavailable' USING ERRCODE='HR409';END IF;PERFORM set_config('htt.company_id',j.company_id::text,true);PERFORM set_config('htt.actor_id',j.owner_id::text,true);PERFORM crm.require_card(p_id);RETURN jsonb_build_object('content',encode(j.content,'base64'),'contentType',j.content_type);END$$;
CREATE FUNCTION crm.finish_card(p_id uuid,p_lease uuid,p_state text,p_error text,p_suggestion jsonb)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.card_jobs;st text:=p_state;err text:=p_error;BEGIN SELECT*INTO j FROM crm.card_jobs WHERE id=p_id FOR UPDATE;IF NOT FOUND OR j.state<>'PROCESSING'OR j.lease_token IS DISTINCT FROM p_lease OR j.lease_until<=now()THEN RAISE EXCEPTION 'Stale card lease' USING ERRCODE='HR409';END IF;IF st NOT IN('SUCCEEDED','RETRY','FAILED','REJECTED')THEN RAISE EXCEPTION 'Invalid completion' USING ERRCODE='HR422';END IF;PERFORM set_config('htt.company_id',j.company_id::text,true);PERFORM set_config('htt.actor_id',j.owner_id::text,true);
 BEGIN PERFORM crm.require_card(p_id);EXCEPTION WHEN insufficient_privilege THEN st:='FAILED';err:='card_access_changed';END;
 IF st='SUCCEEDED'THEN PERFORM crm.validate_draft('CONTACT',j.customer_id,p_suggestion-ARRAY['organization','storeName']);END IF;IF st='RETRY'AND j.attempts>=5 THEN st:='FAILED';END IF;
 UPDATE crm.card_jobs SET state=st,last_error=left(err,100),suggestion=CASE WHEN st='SUCCEEDED'THEN p_suggestion ELSE NULL END,lease_token=NULL,lease_until=NULL,available_at=now()+make_interval(secs=>power(2,j.attempts)::int)WHERE id=p_id;
END$$;
CREATE FUNCTION crm.confirm_card(p_id uuid,p_data jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.card_jobs;fid uuid;BEGIN PERFORM crm.require_card(p_id);PERFORM crm.lock_mobile_head();PERFORM crm.require_card(p_id);SELECT*INTO j FROM crm.card_jobs WHERE company_id=core.current_company()AND id=p_id FOR UPDATE;IF j.state<>'SUCCEEDED'OR j.draft_id IS NOT NULL THEN RAISE EXCEPTION 'Confirm a successful unconsumed card result' USING ERRCODE='HR409';END IF;fid:=gen_random_uuid();PERFORM crm.create_mobile_draft(fid,'CONTACT',j.customer_id,p_data);UPDATE crm.card_jobs SET draft_id=fid WHERE id=p_id;RETURN crm.draft_json(fid);END$$;
REVOKE ALL ON FUNCTION crm.require_card(uuid),crm.card_view(uuid),crm.queue_card(uuid,text,bytea),crm.retry_card(uuid),crm.claim_card(),crm.load_card(uuid,uuid),crm.finish_card(uuid,uuid,text,text,jsonb),crm.confirm_card(uuid,jsonb)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION crm.require_card(uuid),crm.card_view(uuid),crm.queue_card(uuid,text,bytea),crm.retry_card(uuid),crm.confirm_card(uuid,jsonb)TO htt_app;
GRANT EXECUTE ON FUNCTION crm.claim_card(),crm.load_card(uuid,uuid),crm.finish_card(uuid,uuid,text,text,jsonb)TO htt_worker;

CREATE FUNCTION crm.revoke_mobile_device(p uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.mobile.sync');UPDATE crm.mobile_devices SET active=false WHERE company_id=core.current_company()AND id=p AND actor_id=core.current_actor();IF NOT FOUND THEN RAISE EXCEPTION 'Owned device unavailable' USING ERRCODE='42501';END IF;END$$;
REVOKE ALL ON FUNCTION crm.revoke_mobile_device(uuid)FROM PUBLIC;GRANT EXECUTE ON FUNCTION crm.revoke_mobile_device(uuid)TO htt_app;
GRANT USAGE ON SCHEMA crm TO htt_worker;
